$ErrorActionPreference='Stop';$Tag=if($env:CLAUDE_SEO_TAG){$env:CLAUDE_SEO_TAG}else{'v2.3.1'};$Commit=if($env:CLAUDE_SEO_COMMIT){$env:CLAUDE_SEO_COMMIT}else{'55c7914a3ed2869b217b5d5f360a4e7ba28b4848'};$Tmp=Join-Path ([IO.Path]::GetTempPath()) ('claude-seo-'+[guid]::NewGuid().ToString('N'));try{git clone --quiet --depth 1 --branch $Tag https://github.com/AgriciDaniel/claude-seo.git $Tmp;if($LASTEXITCODE-ne 0){throw 'Clone failed'};$Actual=(git -C $Tmp rev-parse HEAD).Trim();if($Actual-ne $Commit){throw "Source mismatch: $Actual"};$env:CLAUDE_SEO_TAG=$Tag;powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $Tmp 'install.ps1');if($LASTEXITCODE-ne 0){throw 'Installer failed'}}finally{if(Test-Path $Tmp){Remove-Item -Recurse -Force $Tmp}}
